   {"text": "The horizontal side", "feedback": "Orientation on the page means nothing — rotate the triangle and the hypotenuse stays itself."},
   {"text": "Either of the two sides that meet to form the right angle", "feedback": "Those are the legs. The hypotenuse faces the right angle from across the triangle."},
   {"text": "The side opposite the smallest angle", "feedback": "Opposite the smallest angle sits the SHORTEST side."},
   {"text": "The side opposite the right angle, always the longest", "feedback": "Correct."}
 ]'::jsonb,
 null),
('MPM2D', 'trigonometry', 'the-primary-trig-ratios', 7, 'Easy',
 'Relative to angle θ in a right triangle, sin θ equals what?', 0,
 '[
   {"text": "Opposite over hypotenuse", "feedback": "Correct."},
   {"text": "Hypotenuse over opposite", "feedback": "The hypotenuse goes UNDERNEATH for sine."},
   {"text": "Adjacent over hypotenuse", "feedback": "Adjacent over hypotenuse is COSINE. SOH: sine takes the opposite side."},
   {"text": "Opposite over adjacent", "feedback": "That ratio is tangent, the TOA in the memory aid."}
 ]'::jsonb,
 null),
