   {"text": "5/3", "feedback": "This is upside down, and bigger than 1, which no cosine in a right triangle can be."},
   {"text": "3/5", "feedback": "Correct. CAH gives 9/15, and dividing both by 3 gives 3/5."}
 ]'::jsonb,
